-- Migration 005: Double-entry ledger and payments
CREATE TYPE ledger_account_type AS ENUM ('ASSET_PROCESSOR_RECEIVABLE','LIABILITY_CUSTOMER_WALLET','LIABILITY_CREATOR_PAYABLE','LIABILITY_ESCROW_MARKETPLACE','LIABILITY_DISPUTE_RESERVE','REVENUE_PLATFORM_SUBSCRIPTION_FEE','REVENUE_PLATFORM_PPV_FEE','REVENUE_PLATFORM_TIP_FEE','REVENUE_PLATFORM_SERVICE_FEE','EXPENSE_PROCESSOR_FEE');
CREATE TYPE entry_type AS ENUM ('WALLET_DEPOSIT','SUBSCRIPTION_PURCHASE','PPV_PURCHASE','TIP_TRANSFER','ESCROW_LOCK','ESCROW_RELEASE','PAYOUT_DISBURSEMENT','REFUND','CHARGEBACK','RESERVE_HOLD');
CREATE TABLE ledger_accounts (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),account_type ledger_account_type NOT NULL,owner_user_id UUID REFERENCES users(id),currency VARCHAR(3) NOT NULL DEFAULT 'USD',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(account_type,owner_user_id,currency));
CREATE TABLE ledger_transactions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),idempotency_key VARCHAR(128) UNIQUE NOT NULL,entry_type entry_type NOT NULL,reference_entity_type VARCHAR(50) NOT NULL,reference_entity_id UUID NOT NULL,description TEXT NOT NULL,metadata JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE ledger_entries (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),transaction_id UUID NOT NULL REFERENCES ledger_transactions(id) ON DELETE RESTRICT,account_id UUID NOT NULL REFERENCES ledger_accounts(id) ON DELETE RESTRICT,amount_cents BIGINT NOT NULL,running_balance_after_cents BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
